Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('a31863364fc482abf60f9ecffcf8caeb12bee3f13ddf1b361ba5493b02d1d96a',), event=Revised(decision='webalgebra', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title='The web app is held to the same standard as the Rust: a closed PageState, a pure step and an idempotent draw', body='*The web app is held to the same standard* (the owner, 2026-09-16; contract `docs/WEB-SPEC.md`): a page is a closed `PageState` with a pure `step(state, event)` and an idempotent `draw` over one `Source` (`web/src/algebra/source.ts`), never a closure of flags; every law in the spec names the node test that pins it, over a seeded generator (`web/test/gen.ts`); the Rust writes vectors under `app/api/tests/web/` that the pure modules must agree with; the `innerHTML` door and a cast ceiling in `scripts/web-static.sh`, the ceiling only moving down.', rationale='The owner, 2026-09-16 (docs/WEB-SPEC.md). Restated 2026-11-20: the names moved with the crate split of 2026-11-18, and the series plan was deleted.', supersedes=()))